if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require dirname(__DIR__).'/bootstrap.php';if(!Refugio\Support\Env::bool('MARKETING_SYNC_CRON_ENABLED',true)){fwrite(STDOUT,"Sincronizacao automatica de marketing desativada.\n");exit(0);}$db=Refugio\Config\Database::connection();$repo=new Refugio\Repositories\MarketingRepository($db);$id=0;$days=max(1,min(366,Refugio\Support\Env::int('MARKETING_SYNC_DAYS_DEFAULT',30)));$start=date('Y-m-d',strtotime('-'.($days-1).' days'));$end=date('Y-m-d');foreach($argv as$arg){if(str_starts_with($arg,'--integracao='))$id=(int)substr($arg,13);elseif(str_starts_with($arg,'--inicio='))$start=substr($arg,9);elseif(str_starts_with($arg,'--fim='))$end=substr($arg,6);} $integrations=$id?array_filter([$repo->findIntegration($id)]):array_filter($repo->integrations(true),static fn($i)=>$i['status']==='CONECTADA');foreach($integrations as$i){$stats=(new Refugio\Services\MarketingSyncService($db))->sync((int)$i['id'],$start,$end);fwrite(STDOUT,$i['provider'].' #'.$i['id'].': '.json_encode($stats,JSON_UNESCAPED_UNICODE).PHP_EOL);}
